const q=document.getElementById('question'), btn=document.getElementById('ask'), result=document.getElementById('result');
document.querySelectorAll('[data-q]').forEach(x=>x.onclick=()=>{q.value=x.dataset.q; ask()}); btn.onclick=ask; q.addEventListener('keydown',e=>{if(e.key==='Enter')ask()});
async function ask(){ const text=q.value.trim(); if(!text){return} result.classList.remove('hidden'); result.innerHTML='<div class="tag">ORCHESTRATOR</div><h2>Mengumpulkan bukti…</h2><p>Intent → location → source ranking → evidence → confidence.</p>'; try{ const r=await fetch('/api/ask?q='+encodeURIComponent(text)); const d=await r.json(); result.innerHTML=`<div class="tag">HASIL ANALISIS</div><h2>${escapeHtml(d.summary)}</h2><p><b>Confidence:</b> ${d.confidence}% · <b>Evidence:</b> ${escapeHtml(d.evidence_strength)}</p><div class="grid"><div class="card"><div class="tag">INTENT</div><pre>${escapeHtml(JSON.stringify(d.intent,null,2))}</pre></div><div class="card wide"><div class="tag">SOURCES / EVIDENCE</div>${d.sources.map(s=>`<p>• ${escapeHtml(s.source)} — ${escapeHtml(s.metric)}: <b>${escapeHtml(String(s.value))} ${escapeHtml(s.unit)}</b></p>`).join('')}</div></div><p><b>Ketidakpastian:</b> ${d.uncertainty.map(escapeHtml).join(' · ')}</p>` }catch(e){result.innerHTML='<div class="tag">ERROR</div><h2>API demo belum berjalan.</h2><p>Jalankan <code>python3 backend/server.py</code> dari folder ipm_v2.</p>'}}
function escapeHtml(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
